#include "../../framework/unity.h"
#include "../../../kernel/x509_der.h"
static const uint8_t certificate[]={0x30,0x4b,0x30,0x40,0x02,0x01,0x01,0x30,0x03,0x06,0x01,0x2a,0x30,0x00,0x30,0x1e,0x17,0x0d,'2','6','0','1','0','1','0','0','0','0','0','0','Z',0x17,0x0d,'2','7','0','1','0','1','0','0','0','0','0','0','Z',0x30,0x00,0x30,0x12,0x30,0x03,0x06,0x01,0x2a,0x03,0x0b,0x00,0x30,0x08,0x02,0x01,0x01,0x02,0x03,0x01,0x00,0x01,0x30,0x03,0x06,0x01,0x2a,0x03,0x02,0x00,0x00};
void test_der_tlv_bounds(void){der_tlv_view_t view;uint8_t short_tlv[]={0x02,0x01,0x01},bad[]={0x30,0x82,0x01};TEST_ASSERT_EQUAL(0,der_tlv_parse(short_tlv,sizeof(short_tlv),&view));TEST_ASSERT_EQUAL(0x02,view.tag);TEST_ASSERT_EQUAL(1,view.length);TEST_ASSERT_EQUAL(3,view.total_length);TEST_ASSERT_NOT_EQUAL(0,der_tlv_parse(bad,sizeof(bad),&view));}
void test_x509_minimal_rsa_view(void){x509_certificate_view_t view;TEST_ASSERT_EQUAL(0,x509_certificate_parse(certificate,sizeof(certificate),&view));TEST_ASSERT_EQUAL(sizeof(certificate),view.certificate_length);TEST_ASSERT_EQUAL(1,view.serial_length);TEST_ASSERT_EQUAL(1,view.serial[0]);TEST_ASSERT_EQUAL(13,view.not_before_length);TEST_ASSERT_EQUAL('2',view.not_before[0]);TEST_ASSERT_EQUAL(1,view.rsa_modulus_length);TEST_ASSERT_EQUAL(1,view.rsa_modulus[0]);TEST_ASSERT_EQUAL(3,view.rsa_exponent_length);TEST_ASSERT_EQUAL(1,view.rsa_exponent[0]);TEST_ASSERT_EQUAL(1,view.rsa_exponent[2]);TEST_ASSERT_NOT_EQUAL(0,x509_certificate_parse(certificate,sizeof(certificate)-1U,&view));}
int main(void){unity_init();RUN_TEST(test_der_tlv_bounds);RUN_TEST(test_x509_minimal_rsa_view);unity_print_results();unity_cleanup();return unity_stats.tests_failed==0?0:1;}
